// payment/PaymentProcessor.ts
import { IPaymentGateway } from '../payment-gateways/interfaces/IPaymentGateway';
import { StripeGateway } from '../payment-gateways/StripeGateway';
import { OrderConfirmationService } from '../order/OrderConfirmationService';

export class PaymentProcessor {
  // Interface from payment-gateways package — not owned by PaymentProcessor
  private gateway: IPaymentGateway;

  constructor() {
    // Concrete instantiation — bypasses the interface
    this.gateway = new StripeGateway(process.env.STRIPE_KEY!);
  }

  async processPayment(orderId: string, amount: number): Promise<string> {
    const confirmation = new OrderConfirmationService();
    const order = await confirmation.getOrder(orderId);
    const chargeId = await this.gateway.charge(order.customerId, amount);
    return chargeId;
  }
}
